<script setup>
import { ref, computed, watch, nextTick } from 'vue';
import { brewApi } from '../api';
import WaterAdjustmentTaskDrawer from './WaterAdjustmentTaskDrawer.vue';
import MaterialReceipt from './MaterialReceipt.vue';
const props = defineProps({ task: Object });
const waterNode=ref(null);
const emit = defineEmits(['close', 'changed']);
const currentTask = ref(props.task), saving = ref(false), error = ref(''), values = ref({});
watch(() => props.task, task => { currentTask.value = task; });
const refreshing = ref(false);
async function refreshTask() {
  if (saving.value || refreshing.value || !currentTask.value?.plan?.id) return;
  const taskId = currentTask.value.id;
  refreshing.value = true; error.value = '';
  try {
    const progress = await brewApi.getPlanProgress(currentTask.value.plan.id);
    if (currentTask.value?.id !== taskId) return;
    const task = progress.tasks.find(item => String(item.id) === String(taskId));
    if (!task) throw new Error('当前任务已不存在，请关闭清单并刷新任务列表。');
    currentTask.value = task; emit('changed');
  } catch (cause) { if (currentTask.value?.id === taskId) error.value = cause.message || '刷新失败，请重试。'; }
  finally { refreshing.value = false; }
}
const list = ref(null);
const checkpoints = computed(() => currentTask.value?.execution_checkpoints || []);
const completed = computed(() => checkpoints.value.filter(node => node.state === 'done').length);
const activeIndex = computed(() => { const main = checkpoints.value.findIndex(node => node.state !== 'done' && node.can_execute_now && !node.parallel_after); return main >= 0 ? main : checkpoints.value.findIndex(node => node.state !== 'done' && (node.can_execute_now ?? true)); });
function isCurrent(index) { return checkpoints.value[index]?.can_execute_now ?? index === activeIndex.value; }
async function revealCurrent() { await nextTick(); list.value?.querySelector('.current')?.scrollIntoView({ behavior: 'smooth', block: 'nearest' }); }
const canOperate = computed(() => currentTask.value?.is_assignee && currentTask.value?.can_execute && !['done','cancelled'].includes(currentTask.value?.state));
function checkpointCompletedTime(value) { if (!value) return ''; return new Date(/[zZ]|[+-]\d\d:\d\d$/.test(value) ? value : `${value}Z`).toLocaleString('zh-CN', { hour12: false }); }
function checkpointDate(node, checkpoints) { const anchor = checkpoints.find(item => item.code === node.timer_from); if (!anchor?.completed_at) return '等待计时开始'; return checkpointCompletedTime(new Date(Date.parse(`${anchor.completed_at}Z`) + Number(node.due_after_min) * 60000).toISOString()); }
async function confirmMashCheckpoint(node, value = '') {
  if (node.input_mode === 'number' && (value === '' || !Number.isFinite(Number(value)))) { error.value = '请输入有效数字后再确认。'; return; }
  saving.value = true; error.value = '';
  try { currentTask.value = await brewApi.taskAction(currentTask.value.id, 'checkpoint', { version: currentTask.value.version, checkpoint_key: node.code, value }); values.value[node.code] = ''; emit('changed'); await revealCurrent(); }
  catch (cause) { error.value = cause.message || '节点确认失败。'; if (cause.status === 409) emit('changed'); }
  finally { saving.value = false; }
}
async function acknowledgeMaterials() {
  if (!window.confirm('确认已核对全部原料的实物、批次和数量，且与发料明细一致？有差异请先联系库管收回重发。')) return;
  saving.value = true; error.value = '';
  try { currentTask.value = await brewApi.taskAction(currentTask.value.id, 'acknowledge-materials', { version: currentTask.value.version }); emit('changed'); await revealCurrent(); }
  catch (cause) { error.value = cause.message; }
  finally { saving.value = false; }
}
async function completeMashExecution() {
  saving.value = true; error.value = '';
  try { currentTask.value = await brewApi.taskAction(currentTask.value.id, 'submit', { version: currentTask.value.version, comment: '糖化执行节点已全部确认' }); emit('changed'); }
  catch (cause) { error.value = cause.message || '糖化任务完成失败。'; if (cause.status === 409) emit('changed'); }
  finally { saving.value = false; }
}
</script>
<template>
    <div v-if="currentTask" class="equipment-modal-mask" @click.self="emit('close')"><section class="equipment-modal mash-execution-modal" role="dialog" aria-modal="true" aria-label="糖化执行清单"><div class="equipment-modal-header"><div><div class="modal-title">糖化执行清单</div><div class="modal-subtitle">{{ currentTask.plan?.name }}<template v-if="currentTask.batch"> · {{ currentTask.batch.name }}</template> · {{ currentTask.plan?.product || currentTask.name }}</div></div><button class="equipment-close" type="button" aria-label="关闭清单" @click="emit('close')">×</button></div><div class="equipment-modal-body mash-execution-body"><MaterialReceipt :receipt="currentTask.material_receipt" :plan="currentTask.plan" :batch="currentTask.batch" :can-operate="canOperate" :saving="saving || refreshing" @acknowledge="acknowledgeMaterials" /><div class="mash-overview"><div><span class="mash-eyebrow">执行进度</span><strong>{{ completed }}<small> / {{ checkpoints.length }} 项</small></strong></div><div class="mash-overview-progress"><progress :value="completed" :max="checkpoints.length || 1"></progress><span>{{ activeIndex < 0 ? '全部节点已完成' : '当前：' + checkpoints[activeIndex].title }}</span></div></div><p class="mash-sequence-hint">主流程按顺序完成；准备洗糟水可在糖化期间并行处理，开始洗糟前须完成。</p><div v-if="error" class="master-error">{{ error }}</div><p v-if="currentTask.execution_blocked_reason" class="mash-blocked-hint" role="status">{{ currentTask.execution_blocked_reason }}</p><p v-if="!canOperate" class="rw-hint">仅任务负责人可执行，当前展示已记录的节点和实测结果。</p><ol ref="list" class="mash-checkpoint-list"><li v-for="(node, index) in checkpoints" :key="node.code" class="mash-checkpoint" :class="{ done: node.state === 'done', current: canOperate && node.state !== 'done' && isCurrent(index) }"><div class="mash-checkpoint-number">{{ node.state === 'done' ? '✓' : String(index + 1).padStart(2,'0') }}</div><div class="mash-checkpoint-main"><div class="mash-checkpoint-title">{{ node.title }}</div><div v-if="node.state === 'done' && node.completed_at" class="mash-checkpoint-meta">完成时间：{{ checkpointCompletedTime(node.completed_at) }}<span v-if="node.completed_by"> · {{ node.completed_by }}</span></div><div v-if="node.value !== undefined && node.value !== ''" class="mash-checkpoint-meta">实测 / 操作结果：{{ node.value }} {{ node.unit || '' }}</div><div v-if="node.target" class="mash-checkpoint-meta">{{ node.temperature !== undefined ? '目标 ' + node.temperature + '℃ · ' + node.duration_min + ' 分钟' : node.quantity !== undefined ? '用量 ' + node.quantity + (node.unit || '') : node.target }}</div><div v-if="node.last_result" class="mash-checkpoint-warning">上次检查：{{ node.last_result }}。处理后重新检查，合格才能继续。</div><div v-if="node.timer_from" class="mash-checkpoint-timer">{{ node.state === 'done' ? '已确认' : (checkpointDate(node, checkpoints) ? '预计完成 ' + checkpointDate(node, checkpoints) : '确认开始后计时 ' + node.due_after_min + ' 分钟') }}</div><div v-if="canOperate && node.state !== 'done' && isCurrent(index)" class="mash-checkpoint-control"><button v-if="node.input_mode==='water'" class="btn btn-xs btn-primary" type="button" @click="waterNode=node">填写实际水质调节</button><template v-else-if="node.input_mode === 'choice'"><button v-for="choice in node.choices || []" :key="choice" class="btn btn-xs btn-outline" type="button" :disabled="saving || refreshing || !!currentTask.execution_blocked_reason" @click="confirmMashCheckpoint(node, choice)">{{ choice }}</button></template><template v-else-if="node.input_mode === 'number'"><input v-model="values[node.code]" type="number" step="any" :placeholder="'输入' + (node.title || '实测值')"><span>{{ node.unit || (node.target === '℃' || node.target?.startsWith('℃') ? '℃' : node.target === 'L' ? 'L' : '') }}</span><button class="btn btn-xs btn-primary" type="button" :disabled="saving || refreshing || !!currentTask.execution_blocked_reason" @click="confirmMashCheckpoint(node, values[node.code])">确认</button></template><template v-else-if="node.input_mode === 'text'"><input v-model="values[node.code]" type="text" placeholder="填写记录"><button class="btn btn-xs btn-primary" type="button" :disabled="saving || refreshing || !!currentTask.execution_blocked_reason || !values[node.code]?.trim()" @click="confirmMashCheckpoint(node, values[node.code])">确认</button></template><button v-else class="btn btn-xs btn-primary" type="button" :disabled="saving || refreshing || !!currentTask.execution_blocked_reason" @click="confirmMashCheckpoint(node)">{{ saving ? '提交中…' : node.code === 'confirm_materials' ? '确认实际领料' : '完成此项并继续' }}</button></div></div><span v-if="node.state === 'done'" class="tag tag-success">已完成</span><span v-else-if="isCurrent(index)" class="mash-current-tag">{{ node.parallel_after ? '并行准备' : '当前任务' }}</span><span v-else class="mash-pending-tag">待执行</span></li></ol></div><div class="equipment-modal-footer"><span class="mash-footer-progress">已完成 {{ completed }} / {{ checkpoints.length }} 项</span><button class="btn btn-secondary" type="button" @click="emit('close')">关闭</button><button class="btn btn-outline" type="button" :disabled="saving || refreshing" @click="refreshTask">{{ refreshing ? '刷新中…' : '刷新进度' }}</button><button v-if="canOperate" class="btn btn-primary" type="button" :disabled="saving || refreshing || !!currentTask.execution_blocked_reason || ['done','cancelled'].includes(currentTask.state) || !(checkpoints).length || (checkpoints).some(node => node.state !== 'done')" @click="completeMashExecution">{{ saving ? '提交中…' : currentTask.state === 'done' ? '糖化任务已完成' : '完成糖化任务' }}</button></div></section></div>
<WaterAdjustmentTaskDrawer v-if="waterNode" :item="{task_id:currentTask.id,version:currentTask.version,checkpoint_key:waterNode.code,title:waterNode.title,water_adjustment:waterNode.water_adjustment,plan_name:currentTask.plan?.name}" @close="waterNode=null" @changed="currentTask=$event;waterNode=null;emit('changed')" />
</template>

<style scoped>
.mash-execution-modal{width:min(860px,calc(100vw - 32px))}.mash-execution-body{padding:24px}.mash-overview{display:flex;align-items:center;gap:30px;padding:20px 22px;border:1px solid #d4a85325;border-radius:12px;background:linear-gradient(110deg,#d4a8530d,transparent)}.mash-eyebrow{display:block;color:var(--text-muted);font-size:11px;margin-bottom:7px}.mash-overview strong{font-size:28px;font-weight:600;color:var(--accent-gold);white-space:nowrap}.mash-overview strong small{font-size:12px;font-weight:400;color:var(--text-muted)}.mash-overview-progress{flex:1;display:grid;gap:10px;font-size:12px;color:var(--text-secondary)}.mash-overview-progress progress{width:100%;height:7px;accent-color:var(--accent-gold);border:0;border-radius:8px;overflow:hidden}.mash-overview-progress progress::-webkit-progress-bar{background:#ffffff0b}.mash-overview-progress progress::-webkit-progress-value{background:var(--accent-gold);border-radius:8px}.mash-sequence-hint{font-size:12px;color:var(--text-muted);margin:16px 2px 20px}.mash-blocked-hint{padding:12px 16px;background:#d4a8530a;border:1px solid #d4a85325;border-radius:8px;color:var(--accent-gold);font-size:12px}.mash-checkpoint-list{padding:0;margin:0;gap:12px}.mash-checkpoint{padding:18px;grid-template-columns:36px minmax(0,1fr) auto;gap:14px;border-radius:11px;background:#ffffff02;scroll-margin:16px}.mash-checkpoint.current{border-color:#d4a85370;background:linear-gradient(110deg,#d4a8530d,#d4a85303)}.mash-checkpoint-number{width:34px;height:34px;border-radius:9px;font-size:12px}.mash-checkpoint-title{font-size:13px;line-height:1.7;font-weight:600}.mash-checkpoint-meta,.mash-checkpoint-timer{font-size:11px;line-height:1.8}.mash-checkpoint.done{background:#8fb68704;border-color:#8fb68720}.mash-checkpoint.done .mash-checkpoint-title{color:var(--text-secondary)}.mash-checkpoint-control{margin-top:12px;gap:10px}.mash-checkpoint-control input{min-height:40px;padding:9px 12px;border-radius:7px;box-sizing:border-box}.mash-checkpoint-control .btn{min-height:36px;padding:8px 14px}.mash-current-tag,.mash-pending-tag{font-size:10px;padding:5px 8px;border-radius:5px;white-space:nowrap}.mash-current-tag{color:var(--accent-gold);background:#d4a85315}.mash-pending-tag{color:var(--text-muted);background:#ffffff05}.mash-footer-progress{margin-right:auto;font-size:12px;color:var(--text-muted)}@media(max-width:560px){.mash-execution-body{padding:16px}.mash-overview{padding:16px;gap:16px}.mash-checkpoint{grid-template-columns:30px minmax(0,1fr);gap:10px;padding:14px}.mash-checkpoint-number{width:28px;height:28px}.mash-checkpoint>.tag,.mash-checkpoint>.mash-current-tag,.mash-checkpoint>.mash-pending-tag{grid-column:2;justify-self:start}.mash-checkpoint-control input{width:100%}.mash-footer-progress{width:100%;margin-bottom:6px}}
</style>
